import numpy as np
from skimage.measure import regionprops

def retained_labels(path):
 m=np.load(path); out=[]
 for r in regionprops(m):
  y0,x0,y1,x1=r.bbox
  if y1==320 or x1==320: continue
  if y0==0 or x0==0: out.append(r.label)
  else:
   ys,xs=np.nonzero(r.image); p=np.column_stack((xs,ys)).astype(float)
   if min(np.ptp(p[:,0]*np.cos(t)+p[:,1]*np.sin(t))+1 for t in np.deg2rad(np.arange(0,180,.5)))>=8.46: out.append(r.label)
 return m,out
for w in ['A01','E03','H01','C01','C02','A03']:
 try:
  n,labs=retained_labels(f'/task/work/masks/{w}_nuclei.npy')
  c=np.load(f'/task/work/{w}_cell_noRS_masks.npy') if __import__('os').path.exists(f'/task/work/{w}_cell_noRS_masks.npy') else np.load(f'/task/work/{w}_cell_test_masks.npy')
  assign=[]
  for lab in labs:
   obj=n==lab; ov=np.bincount(c[obj].ravel());ov[0]=0
   assign.append(int(ov.argmax()) if len(ov)>1 and ov.max()>0 else 0)
  vals,cnts=np.unique(assign,return_counts=True)
  print(w,'retained',len(labs),'assigned',sum(a>0 for a in assign),'missing',sum(a==0 for a in assign),'duplicate_shared_masks',sum(cnts[vals>0]>1),'shared_details',{int(v):int(z) for v,z in zip(vals,cnts) if v>0 and z>1})
 except Exception as e: print(w,'ERROR',e)
